class Solution {
    public int countMirrors(String s) {
        int n = s.length(), total = 0;
        for (int i = 0; i < n; i++)
            for (int j = i; j < n; j++) {
                int a = i, b = j;
                while (a < b && s.charAt(a) == s.charAt(b)) { a++; b--; }
                if (a >= b) total++;
            }
        return total;
    }
}

