class Solution:
    def countMirrors(self, s: str) -> int:
        n, total = len(s), 0
        for c in range(2 * n - 1):
            i, j = c // 2, c // 2 + c % 2
            while i >= 0 and j < n and s[i] == s[j]:
                total += 1
                i, j = i - 1, j + 1
        return total

